/**
 * Página /logistica/recebimento — recebimento livre por bip (sem requisição vinculada).
 *
 * Para fluxos de chegada não-amarrados a uma requisição (transferências
 * avulsas, devoluções, ajustes manuais com etiqueta). O modal sempre aberto;
 * fechar volta pra logística.
 *
 * Para chegada AMARRADA a requisição, use /requisicoes/chegada.
 */
import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useStore } from "@/shared/contexts/StoreContext";
import { EntradaBipModal } from "@/features/logistica/ui/EntradaBipModal";
import { useMiaPageContext } from "@/features/mia/hooks/useMiaPageContext";

export default function RecebimentoBipPage() {
  useMiaPageContext({
    description: 'Recebimento livre por bip de etiqueta QR — para transferências avulsas, devoluções, ajustes manuais.',
    natural_language_hints: '"bipar etiqueta" = scanner de UID; "recebimento" = entrada de produto na loja atual; modal sempre aberto, fechar volta pra /logistica.',
    capabilities: ['bipar_etiqueta', 'confirmar_recebimento'],
    primary_entity: 'etiqueta_qr',
  });
  const navigate = useNavigate();
  const { selectedStore } = useStore();
  const [open, setOpen] = useState(true);

  useEffect(() => { setOpen(true); }, []);

  if (!selectedStore) {
    return (
      <div className="p-8 text-center text-muted-foreground">
        Selecione uma loja para receber.
      </div>
    );
  }

  return (
    <EntradaBipModal
      isOpen={open}
      onClose={() => {
        setOpen(false);
        navigate("/logistica");
      }}
      lojaDestinoId={selectedStore.id}
      lojaDestinoNome={selectedStore.name}
    />
  );
}

