/**
 * Página standalone de separação por bip — carrega a active_session pelo id
 * e abre o SeparacaoBipModal com seus items.
 */
import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { supabase } from "@/integrations/supabase/client";
import { SeparacaoBipModal } from "./SeparacaoBipModal";
import { Card, CardContent } from "@/shared/ui/card";
import { Button } from "@/shared/ui/button";
import { ArrowLeft, AlertTriangle } from "lucide-react";
import { Skeleton } from "@/shared/ui/skeleton";
import { useStore } from "@/shared/contexts/StoreContext";

interface SessionRow {
  session_id: string;
  preparer_name: string;
  store_preparer: string;
  status: string;
}

interface ItemRow {
  id: string;
  item_name: string;
  requested_quantity: number;
  is_separated: boolean;
  qr_uid_bipado?: string | null;
  produto_master_id?: number | null;
  unidade_medida?: string | null;
}

export default function SeparacaoBipPage() {
  const { sessionId } = useParams<{ sessionId: string }>();
  const navigate = useNavigate();
  const { selectedStore } = useStore();
  const [session, setSession] = useState<SessionRow | null>(null);
  const [items, setItems] = useState<ItemRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState<string | null>(null);

  useEffect(() => {
    if (!sessionId) return;
    let cancelled = false;
    setLoading(true);
    setErro(null);

    Promise.all([
      supabase.from("active_sessions").select("session_id, preparer_name, store_preparer, status").eq("session_id", sessionId).maybeSingle(),
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      (supabase.from("active_session_items") as any)
        .select("id, item_name, requested_quantity, is_separated, qr_uid_bipado, produto_master_id, unidade_medida")
        .eq("session_id", sessionId)
        .order("order_index"),
    ]).then(([sRes, iRes]) => {
      if (cancelled) return;
      if (sRes.error || !sRes.data) {
        setErro(sRes.error?.message || "Sessão não encontrada");
        setLoading(false);
        return;
      }
      setSession(sRes.data as SessionRow);
      const itemsData = (iRes.data ?? []) as ItemRow[];
      setItems(itemsData);
      setLoading(false);
    });

    return () => {
      cancelled = true;
    };
  }, [sessionId]);

  if (loading) {
    return (
      <div className="p-4 sm:p-8 max-w-3xl mx-auto space-y-4">
        <Skeleton className="h-12 w-48" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  if (erro || !session) {
    return (
      <div className="p-4 sm:p-8 max-w-2xl mx-auto">
        <Button variant="ghost" size="sm" onClick={() => navigate(-1)} className="gap-2 mb-4 min-h-[44px]">
          <ArrowLeft className="w-4 h-4" /> Voltar
        </Button>
        <Card className="border-red-200">
          <CardContent className="p-4 sm:p-6 flex items-start gap-3 text-red-700">
            <AlertTriangle className="w-5 h-5 flex-shrink-0 mt-0.5" />
            <div className="min-w-0">
              <p className="font-bold">{erro || "Sessão de separação não encontrada"}</p>
              <p className="text-sm text-muted-foreground break-all">ID: {sessionId}</p>
            </div>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <SeparacaoBipModal
      isOpen
      onClose={() => navigate(-1)}
      sessionId={session.session_id}
      sessionLabel={`${session.store_preparer || "—"} → preparado por ${session.preparer_name || "—"}`}
      items={items.map((i) => ({
        id: i.id,
        item_name: i.item_name,
        requested_quantity: i.requested_quantity,
        is_separated: i.is_separated,
        produto_master_id: i.produto_master_id ?? null,
        qr_uid_bipado: i.qr_uid_bipado ?? null,
        unidade_medida: i.unidade_medida ?? 'cx',
      }))}
      lojaPreparadoraId={selectedStore?.id ?? null}
      defaultMode={typeof navigator !== "undefined" && /Android|iPad|iPhone|Mobile|Tablet/i.test(navigator.userAgent) ? "camera" : "bluetooth"}
    />
  );
}

