694	            : `${(slot.unidadeMedida || "caixa").toUpperCase()} ${slot.slotIndex} de ${slot.totalSlots}${slot.qtyInterna ? ` · ${slot.qtyInterna} ${(slot.embalagem || 'un').toLowerCase()}` : ""}`
695	          }
696	        </p>
697	        {slot.uid && (
698	          <p className="text-[10px] font-mono text-muted-foreground mt-0.5 truncate">UID {slot.uid}</p>
699	        )}
700	      </div>
701	    </div>
702	  );
703	}
