/**
 * Modal de separação digital com bip QR.
 *
 * Lê etiqueta_qr → chama RPC bipar_etiqueta(uid,'separacao',ctx) → marca
 * active_session_items.is_separated=true + salva qr_uid_bipado/bipado_at/bipado_por.
 *
 * Cada caixa solicitada (requested_quantity = N) gera N "slots". Bip de uma
 * mesma UID 2x = erro. Bip de produto fora da lista = empilha como "extra".
 */
import { useEffect, useMemo, useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import { Button } from "@/shared/ui/button";
import { ScrollArea } from "@/shared/ui/scroll-area";
import { Bluetooth, Camera, ScanBarcode, ArrowLeft, CheckCircle2, XCircle, Package, AlertTriangle } from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useEtiquetaScanner, playSuccessSound, playWarningSound, playErrorSound, formatBipError, calcularIncrementoBip, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "./CameraScannerStatus";

interface SessionItem {
  id: string;
  item_name: string;
  requested_quantity: number;
  is_separated: boolean;
  produto_master_id?: number | null;
  qr_uid_bipado?: string | null;
  /** Unidade do item (cx, kg, g, l, ml…). Default 'cx' se vazio. */
  unidade_medida?: string | null;
}

interface BipSlot {
  slotId: string;
  itemId: string;
  itemName: string;
  produtoMasterId: number | null;
  slotIndex: number;
  totalSlots: number;
  status: "pending" | "confirmed" | "extra";
  uid?: string;
  payload?: ScannedPayload;
  bipadoAt?: number;
  /** Unidades dentro da caixa (preenchido ao bipar) */
  qtyInterna?: number;
  embalagem?: string | null;
  // Bulk = 1 slot único pro item inteiro (ex: "10 kg"). Senão = N slots discretos.
  isBulkUnit?: boolean;
  unidadeMedida?: string;
  bulkQty?: number;
}

// Bulk = 1 etiqueta cobre a quantidade total. Inclui peso/volume contínuo
// E containers de volume fixo (balde, galão, tambor, barril, garrafa).
const BULK_UNITS = new Set([
  'kg', 'g', 'l', 'litro', 'litros', 'ml', 'liter', 'liters',
  'balde', 'baldes', 'galao', 'galão', 'galões', 'galoes',
  'tambor', 'tambores', 'barril', 'barris', 'garrafa', 'garrafas'
]);
const isBulkMeasure = (u: string | null | undefined) => BULK_UNITS.has((u || '').toLowerCase().trim());

interface Props {
  isOpen: boolean;
  onClose: () => void;
  sessionId: string;
  sessionLabel: string;
  items: SessionItem[];
  lojaPreparadoraId: number | null;
  onItemSeparated?: (itemId: string, uid: string) => void;
  /** Modo padrão do scanner: fábrica usa "bluetooth", loja usa "camera". */
  defaultMode?: "bluetooth" | "camera";
}

function buildSlots(items: SessionItem[]): BipSlot[] {
  const out: BipSlot[] = [];
  items.forEach((item) => {
    const unit = item.unidade_medida || 'cx';
    if (isBulkMeasure(unit)) {
      // Bulk: 1 slot único representa o pedido inteiro (ex: "10 kg" = 1 bip)
      const bulkQty = Number(item.requested_quantity) || 1;
      out.push({
        slotId: `${item.id}-bulk`,
        itemId: item.id,
        itemName: item.item_name,
        produtoMasterId: item.produto_master_id ?? null,
        slotIndex: 1,
        totalSlots: 1,
        status: item.is_separated ? "confirmed" : "pending",
        uid: item.qr_uid_bipado || undefined,
        isBulkUnit: true,
        unidadeMedida: unit,
        bulkQty,
      });
      return;
    }
    // Box: N slots discretos (1 etiqueta por caixa/unidade)
    const total = Math.max(1, Math.round(item.requested_quantity || 1));
    for (let i = 1; i <= total; i++) {
      out.push({
        slotId: `${item.id}-slot-${i}`,
        itemId: item.id,
        itemName: item.item_name,
        produtoMasterId: item.produto_master_id ?? null,
        slotIndex: i,
        totalSlots: total,
        status: item.is_separated && i === 1 ? "confirmed" : "pending",
        uid: item.qr_uid_bipado || undefined,
        unidadeMedida: unit,
      });
    }
  });
  return out;
}

export function SeparacaoBipModal({
  isOpen,
  onClose,
  sessionId,
  sessionLabel,
  items,
  lojaPreparadoraId,
  onItemSeparated,
  defaultMode = "bluetooth",
}: Props) {
  const [slots, setSlots] = useState<BipSlot[]>([]);
  const [mobileTab, setMobileTab] = useState<"pending" | "confirmed" | "extras">("pending");
  // Dialog de transferir separacao
  const [reseparirDialog, setReseparirDialog] = useState<{
    open: boolean;
    uid: string;
    produto: string;
    separada_at: string | null;
    payload: ScannedPayload | null;
  }>({ open: false, uid: "", produto: "", separada_at: null, payload: null });

  useEffect(() => {
    if (!isOpen) return;
    setSlots(buildSlots(items));
  }, [isOpen, items]);

  const handleBip = async (payload: ScannedPayload) => {
    if (!payload.uid) {
      playErrorSound();
      toast.error("Etiqueta sem UID — não rastreável");
      return;
    }

    if (slots.some((s) => s.uid === payload.uid && s.status !== "pending")) {
      playErrorSound();
      toast.error("Caixa já bipada nesta separação");
      return;
    }

    // Chama RPC — fonte única de verdade
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: rpc, error } = await (supabase.rpc as any)("bipar_etiqueta", {
      p_uid: payload.uid,
      p_etapa: "separacao",
      p_contexto: {
        loja_id: lojaPreparadoraId,
        referencia_tipo: "active_session",
        referencia_id: sessionId,
        payload,
      },
    });
    if (error) {
      playErrorSound();
      toast.error(`Falha no bip: ${error.message}`);
      return;
    }
    const result = rpc as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; separada_at?: string | null }; alertas?: string[] };
    if (!result?.ok) {
      // Caso especial: ja separada → dialog pra transferir
      const erroLower = (result?.erro || "").toLowerCase();
      const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const etSep = result?.etiqueta as any;
      if (isJaSeparada && etSep?.separada_at) {
        playWarningSound();
        setReseparirDialog({
          open: true,
          uid: payload.uid,
          produto: etSep.produto_nome_snapshot || "produto",
          separada_at: etSep.separada_at,
          payload,
        });
        return;
      }
      playErrorSound();
      toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }
    (result.alertas ?? []).forEach((a) => toast.warning(a));

    const scannedPid = result.etiqueta?.produto_master_id ?? Number(payload.pid);
    const scannedName = result.etiqueta?.produto_nome_snapshot ?? "";
    const scannedQty = Number(result.etiqueta?.quantidade_interna ?? payload.qty ?? 1);
    const scannedEmb = result.etiqueta?.embalagem_nome ?? null;
    const scannedTipo = result.etiqueta?.tipo_embalagem ?? payload.tipo ?? null;

    // Achar slot pendente correspondente
    const targetIdx = slots.findIndex((s) => s.status === "pending" && s.produtoMasterId === scannedPid);

    // Quantos slots este bip cobre? Pedido bate com tipo da etiqueta → 1.
    // Senão → qty_interna (operador bipa 1 etiqueta, marca N slots de uma vez).
    const slotsCobertos = targetIdx >= 0
      ? calcularIncrementoBip(slots[targetIdx].unidadeMedida, scannedTipo, scannedQty)
      : 1;

    if (targetIdx < 0) {
      // Empilha extra silenciosamente — operador ve no painel "Fora da Lista"
      if (navigator.vibrate) navigator.vibrate([50]);
      setSlots((prev) => [
        ...prev,
        {
          slotId: `extra-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          itemId: "",
          itemName: scannedName || `Produto #${scannedPid}`,
          produtoMasterId: scannedPid,
          slotIndex: 1,
          totalSlots: 1,
          status: "extra",
          uid: payload.uid,
          payload,
          bipadoAt: Date.now(),
          qtyInterna: scannedQty,
          embalagem: scannedEmb,
        },
      ]);
      return;
    }

    const slot = slots[targetIdx];

    // Persiste no item da sessão
    const { data: { user } } = await supabase.auth.getUser();
    const { error: upErr } = await supabase
      .from("active_session_items")
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      .update({
        is_separated: true,
        separated_by: user?.user_metadata?.nome || user?.email || "",
        qr_uid_bipado: payload.uid,
        bipado_at: new Date().toISOString(),
        bipado_por: user?.id ?? null,
      } as any)
      .eq("id", slot.itemId);

    if (upErr) {
      playErrorSound();
      toast.error(`Erro ao salvar separação: ${upErr.message}`);
      return;
    }

    playSuccessSound();
    if (navigator.vibrate) navigator.vibrate(100);
    toast.success(`Separado: ${slot.itemName}`);

    // Marca N slots pendentes deste item de uma vez (N = slotsCobertos).
    // Caso pedido = un (60) + etiqueta = caixa qty 12 → 1 bip marca 12 slots.
    // Caso pedido = caixa (5) + etiqueta = caixa qty 12 → 1 bip marca 1 slot.
    setSlots((prev) => {
      const next = [...prev];
      let marcados = 0;
      for (let i = 0; i < next.length && marcados < slotsCobertos; i++) {
        if (next[i].status === "pending" && next[i].produtoMasterId === scannedPid) {
          next[i] = {
            ...next[i],
            status: "confirmed",
            // Só o primeiro slot do bip carrega o UID — os outros são "preenchidos
            // automaticamente" pela cobertura. Sem isso, o check de "uid já bipada"
            // disparava porque N slots ficavam com mesmo UID.
            uid: marcados === 0 ? payload.uid : undefined,
            payload: marcados === 0 ? payload : undefined,
            bipadoAt: Date.now(),
            qtyInterna: scannedQty,
            embalagem: scannedEmb,
          };
          marcados++;
        }
      }
      return next;
    });

    onItemSeparated?.(slot.itemId, payload.uid);
  };

  const scanner = useEtiquetaScanner({
    enabled: isOpen,
    onScan: handleBip,
    cameraElementId: "separacao-qr-reader",
    onInvalid: () => toast.error("QR ilegível"),
    onDuplicate: () => {
      playErrorSound();
      toast.error("Esta etiqueta já foi bipada");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    },
    initialMode: defaultMode,
  });

  const stats = useMemo(() => {
    const pending = slots.filter((s) => s.status === "pending");
    const confirmed = slots.filter((s) => s.status === "confirmed");
    const extras = slots.filter((s) => s.status === "extra");
    const total = slots.filter((s) => s.status !== "extra").length;
    const unConfirmadas = confirmed.reduce((acc, s) => acc + (s.qtyInterna || 0), 0);
    const unExtras = extras.reduce((acc, s) => acc + (s.qtyInterna || 0), 0);
    return {
      pending,
      confirmed,
      extras,
      unConfirmadas,
      unExtras,
      progress: total > 0 ? Math.round((confirmed.length / total) * 100) : 0,
    };
  }, [slots]);

  const isComplete = stats.pending.length === 0 && stats.confirmed.length > 0;

  // Transfere separacao da req anterior pra esta — sobrescreve separada_at/por
  const confirmarReseparar = async () => {
    if (!reseparirDialog.uid || !reseparirDialog.payload) {
      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
      return;
    }
    const payload = reseparirDialog.payload;
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reseparar", {
        p_uid: reseparirDialog.uid,
        p_contexto: {
          loja_id: lojaPreparadoraId,
          referencia_tipo: "active_session",
          referencia_id: sessionId,
          payload,
        },
      });
      const rpc = rpcRaw as { ok: boolean; erro?: string; etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null } } | null;
      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
        playErrorSound();
        return;
      }

      // Aplica visualmente — marca slots como confirmed igual ao fluxo normal
      const scannedPid = rpc.etiqueta.produto_master_id;
      const scannedQty = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
      const scannedTipo = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;

      const targetIdx = slots.findIndex((s) => s.status === "pending" && s.produtoMasterId === scannedPid);
      if (targetIdx < 0) {
        toast.warning(`Transferida mas produto não está na lista — registrado como extra`);
        setSlots((prev) => [...prev, {
          slotId: `extra-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          itemId: "", itemName: rpc.etiqueta!.produto_nome_snapshot || `Produto #${scannedPid}`,
          produtoMasterId: scannedPid, slotIndex: 1, totalSlots: 1, status: "extra",
          uid: payload.uid, payload, bipadoAt: Date.now(),
          qtyInterna: scannedQty, embalagem: scannedEmb,
        }]);
        return;
      }
      const slotsCobertos = calcularIncrementoBip(slots[targetIdx].unidadeMedida, scannedTipo, scannedQty);
      const slot = slots[targetIdx];
      const { data: { user } } = await supabase.auth.getUser();
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      await supabase.from("active_session_items").update({
        is_separated: true,
        separated_by: user?.user_metadata?.nome || user?.email || "",
        qr_uid_bipado: payload.uid,
        bipado_at: new Date().toISOString(),
        bipado_por: user?.id ?? null,
      } as any).eq("id", slot.itemId);

      setSlots((prev) => {
        const next = [...prev];
        let marcados = 0;
        for (let i = 0; i < next.length && marcados < slotsCobertos; i++) {
          if (next[i].status === "pending" && next[i].produtoMasterId === scannedPid) {
            next[i] = {
              ...next[i], status: "confirmed",
              uid: marcados === 0 ? payload.uid : undefined,
              payload: marcados === 0 ? payload : undefined,
              bipadoAt: Date.now(), qtyInterna: scannedQty, embalagem: scannedEmb,
            };
            marcados++;
          }
        }
        return next;
      });
      playSuccessSound();
      if (navigator.vibrate) navigator.vibrate(100);
      toast.success(`Separação transferida: ${slot.itemName}`);
      onItemSeparated?.(slot.itemId, payload.uid);
    } catch (e) {
      toast.error(`Erro: ${(e as Error).message}`);
      playErrorSound();
    } finally {
      setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null });
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent data-mia-modal="separa-o-por-bip" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
        {/* Header */}
        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
            </Button>
            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">Separação por bip</DialogTitle>
              <p className="text-[11px] sm:text-xs text-muted-foreground truncate">{sessionLabel}</p>
            </div>
          </div>
          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
            <button
              onClick={() => scanner.setScanMode("bluetooth")}
              aria-label="Scanner Bluetooth"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "bluetooth"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
            </button>
            <button
              onClick={() => scanner.setScanMode("camera")}
              aria-label="Scanner por câmera"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "camera"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
            </button>
          </div>
        </div>

        {/* Progress */}
        <div className="px-5 py-3 flex-shrink-0 border-b border-border/50">
          <div className="flex items-center justify-between mb-2">
            <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Progresso</span>
            <span className={cn("text-xl font-black tabular-nums", isComplete ? "text-emerald-600" : "text-[#57715B]")}>{stats.progress}%</span>
          </div>
          <div className="w-full h-2.5 bg-[#57715B]/10 dark:bg-white/10 rounded-full overflow-hidden">
            <div
              className={cn(
                "h-full rounded-full transition-all duration-700 ease-out",
                isComplete ? "bg-emerald-500 shadow-[0_0_12px_rgba(16,185,129,0.5)]" : "bg-[#57715B]"
              )}
              style={{ width: `${stats.progress}%` }}
            />
          </div>
          <div className="flex flex-wrap items-center gap-x-3 gap-y-1 mt-2">
            <span className="flex items-center gap-1.5 text-[11px] sm:text-xs"><span className="w-2.5 h-2.5 rounded-full bg-red-500" /> Pendentes <b>{stats.pending.length}</b></span>
            <span className="flex items-center gap-1.5 text-[11px] sm:text-xs"><span className="w-2.5 h-2.5 rounded-full bg-emerald-500" /> Separados <b>{stats.confirmed.length}</b> <span className="text-muted-foreground">({stats.unConfirmadas} un)</span></span>
            {stats.extras.length > 0 && (
              <span className="flex items-center gap-1.5 text-[11px] sm:text-xs"><span className="w-2.5 h-2.5 rounded-full bg-orange-500" /> Extras <b>{stats.extras.length}</b> <span className="text-muted-foreground">({stats.unExtras} un)</span></span>
            )}
          </div>
        </div>

        {/* Scanner input invisível */}
        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}

        {/* Body */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          {scanner.scanMode === "camera" ? (
            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
              <CameraScannerStatus
                starting={scanner.cameraStarting}
                error={scanner.cameraError}
                onRetry={scanner.retryCamera}
              />
            </div>
          ) : (
            <div
              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
            >
              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
              </div>
              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Escaneando...</h3>
              <p className="text-[11px] text-muted-foreground text-center mt-1">Aponte o leitor para as etiquetas</p>
            </div>
          )}

          {/* Kanban */}
          <div className="flex-1 flex flex-col overflow-hidden">
            {/* Mobile tabs (md:hidden) */}
            <div className="md:hidden flex p-1 mx-2 mt-2 rounded-xl bg-muted/40 dark:bg-zinc-800/60 flex-shrink-0">
              <MobileTab active={mobileTab === "pending"} onClick={() => setMobileTab("pending")} accent="red">
                Pend. <span className="font-black">{stats.pending.length}</span>
              </MobileTab>
              <MobileTab active={mobileTab === "confirmed"} onClick={() => setMobileTab("confirmed")} accent="emerald">
                Sep. <span className="font-black">{stats.confirmed.length}</span>
              </MobileTab>
              {stats.extras.length > 0 && (
                <MobileTab active={mobileTab === "extras"} onClick={() => setMobileTab("extras")} accent="orange">
                  Extras <span className="font-black">{stats.extras.length}</span>
                </MobileTab>
              )}
            </div>

            <div className="flex-1 flex md:flex-row flex-col overflow-hidden p-2 gap-2">
              <KanbanColumn
                title="Pendentes"
                accent="red"
                icon={<XCircle className="w-4 h-4" />}
                items={stats.pending}
                hiddenOnMobile={mobileTab !== "pending"}
                empty={
                  <div className="flex flex-col items-center justify-center py-16 text-emerald-500/40">
                    <CheckCircle2 className="w-12 h-12 mb-2" />
                    <p className="text-sm font-semibold">Tudo separado!</p>
                  </div>
                }
              />
              <KanbanColumn
                title="Separados"
                accent="emerald"
                icon={<CheckCircle2 className="w-4 h-4" />}
                items={stats.confirmed}
                hiddenOnMobile={mobileTab !== "confirmed"}
                empty={<p className="text-xs text-muted-foreground p-4">Nenhum bip ainda.</p>}
              />
              {stats.extras.length > 0 && (
                <KanbanColumn
                  title="Extras"
                  accent="orange"
                  icon={<AlertTriangle className="w-4 h-4" />}
                  items={stats.extras}
                  hiddenOnMobile={mobileTab !== "extras"}
                  empty={null}
                />
              )}
            </div>
          </div>
        </div>

        {/* Footer */}
        <div
          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between flex-shrink-0 gap-2"
          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
        >
          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
            {isComplete ? "Separação completa." : `${stats.pending.length} caixa(s) pendente(s).`}
          </p>
          <Button data-mia-action="on-close" onClick={onClose} variant={isComplete ? "default" : "outline"} className="h-11 flex-shrink-0">
            {isComplete ? "Concluir" : "Fechar"}
          </Button>
        </div>
      </DialogContent>

      {/* AlertDialog — transferir separacao de outra requisicao */}
      <AlertDialog open={reseparirDialog.open} onOpenChange={(o) => !o && setReseparirDialog({ open: false, uid: "", produto: "", separada_at: null, payload: null })}>
        <AlertDialogContent className="max-w-md rounded-3xl">
          <AlertDialogHeader>
            <AlertDialogTitle className="text-lg font-bold text-orange-700 flex items-center gap-2">
              <AlertTriangle className="w-5 h-5" />
              Etiqueta já separada
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-3 text-sm">
                <p>
                  <b className="text-foreground">{reseparirDialog.produto}</b> já foi separada{" "}
                  {reseparirDialog.separada_at && (
                    <span className="text-foreground">
                      em <b>{new Date(reseparirDialog.separada_at).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" })}</b>
                    </span>
                  )} (em outra requisição).
                </p>
                <p className="text-orange-700 font-semibold">
                  Deseja transferir a separação para esta requisição?
                </p>
                <p className="text-xs text-muted-foreground">
                  A etiqueta passa a contar para esta requisição. O histórico fica registrado na timeline.
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel className="rounded-xl">Cancelar</AlertDialogCancel>
            <AlertDialogAction onClick={confirmarReseparar} className="bg-orange-600 hover:bg-orange-700 rounded-xl">
              Transferir separação
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Dialog>
  );
}

function MobileTab({
  active,
  onClick,
  accent,
  children,
}: {
  active: boolean;
  onClick: () => void;
  accent: "red" | "emerald" | "orange";
  children: React.ReactNode;
}) {
  const activeMap = {
    red: "bg-red-500/10 text-red-700 dark:text-red-300 ring-1 ring-red-500/40",
    emerald: "bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 ring-1 ring-emerald-500/40",
    orange: "bg-orange-500/10 text-orange-700 dark:text-orange-300 ring-1 ring-orange-500/40",
  };
  return (
    <button
      onClick={onClick}
      className={cn(
        "flex-1 min-h-[44px] px-3 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-all",
        active ? activeMap[accent] : "text-muted-foreground hover:text-foreground"
      )}
    >
      {children}
    </button>
  );
}

function KanbanColumn({
  title,
  accent,
  icon,
  items,
  empty,
  hiddenOnMobile = false,
}: {
  title: string;
  accent: "red" | "emerald" | "orange";
  icon: React.ReactNode;
  items: BipSlot[];
  empty: React.ReactNode;
  hiddenOnMobile?: boolean;
}) {
  const accentMap = {
    red: "border-red-500/60 dark:border-red-400/50 shadow-[0_0_15px_-3px_rgba(239,68,68,0.3)] text-red-600 dark:text-red-400",
    emerald: "border-emerald-500/60 dark:border-emerald-400/50 shadow-[0_0_15px_-3px_rgba(16,185,129,0.3)] text-emerald-600 dark:text-emerald-400",
    orange: "border-orange-500/60 dark:border-orange-400/50 shadow-[0_0_15px_-3px_rgba(249,115,22,0.3)] text-orange-600 dark:text-orange-400",
  };
  return (
    <div
      className={cn(
        "flex-1 flex flex-col min-w-0 rounded-[1.5rem] overflow-hidden border-2 bg-white/20 dark:bg-white/5 backdrop-blur-md",
        accentMap[accent],
        hiddenOnMobile && "hidden md:flex"
      )}
    >
      <div className="px-4 py-3 border-b border-border/30 flex items-center justify-between flex-shrink-0">
        <div className="flex items-center gap-2 min-w-0">
          {icon}
          <span className="text-xs font-bold uppercase tracking-wider truncate">{title}</span>
        </div>
        <span className="text-sm font-black flex-shrink-0">{items.length}</span>
      </div>
      <ScrollArea className="flex-1">
        <div className="p-2.5 space-y-2">
          {items.length === 0 ? empty : items.map((slot) => <SlotCard key={slot.slotId} slot={slot} />)}
        </div>
      </ScrollArea>
    </div>
  );
}

function SlotCard({ slot }: { slot: BipSlot }) {
  return (
    <div className="rounded-2xl bg-white dark:bg-zinc-900 border border-border/40 p-3 flex items-start gap-3">
      <div className="h-9 w-9 rounded-xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
        <Package className="h-4 w-4 text-[#57715B]" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold leading-tight truncate">{slot.itemName}</p>
        <p className="text-[10px] uppercase tracking-wider text-muted-foreground mt-0.5">
          {slot.isBulkUnit
            ? `${slot.bulkQty ?? slot.qtyInterna ?? '?'} ${(slot.unidadeMedida || '').toUpperCase()}`
            : `${(slot.unidadeMedida || "caixa").toUpperCase()} ${slot.slotIndex} de ${slot.totalSlots}${slot.qtyInterna ? ` · ${slot.qtyInterna} ${(slot.embalagem || 'un').toLowerCase()}` : ""}`
          }
        </p>
        {slot.uid && (
          <p className="text-[10px] font-mono text-muted-foreground mt-0.5 truncate">UID {slot.uid}</p>
        )}
      </div>
    </div>
  );
}

content.content:
1	/**
2	 * Modal de recebimento na loja com bip QR.
3	 *
4	 * Operador da loja destino bipa cada caixa que está descarregando.
5	 * Para cada UID:
6	 *   1. RPC bipar_etiqueta(uid, 'entrada', { loja_id }) — atomic state machine
7	 *   2. INSERT movimentacoes (tipo='entrada', etiqueta_qr_uid, lote_id, qty)
8	 *   3. Trigger atualizar_estoque_e_alertas atualiza estoque automaticamente
9	 *
10	 * Lista cumulativa de caixas recebidas, com toast por bip.
11	 */
12	import { useMemo, useState } from "react";
13	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
14	import { Button } from "@/shared/ui/button";
15	import { ScrollArea } from "@/shared/ui/scroll-area";
16	import { Bluetooth, Camera, ScanBarcode, ArrowLeft, Package, MapPin, AlertTriangle, RefreshCw, Boxes } from "lucide-react";
17	import { toast } from "sonner";
18	import { Link } from "react-router-dom";
19	import { cn } from "@/shared/lib/utils";
20	import { supabase } from "@/integrations/supabase/client";
21	import { useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound, formatBipError, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
22	import { CameraScannerStatus } from "./CameraScannerStatus";
23	
24	interface RecebidoItem {
25	  uid: string;
26	  produto_master_id: number;
27	  produto_nome: string;
28	  lote_codigo: string | null;
29	  lote_id: string | null;
30	  quantidade: number;
31	  embalagem: string | null;
32	  recebido_at: number;
33	  alertas: string[];
34	  backfilled: boolean;
35	}
36	
37	interface Props {
38	  isOpen: boolean;
39	  onClose: () => void;
40	  lojaDestinoId: number;
41	  lojaDestinoNome: string;
42	}
43	
44	export function EntradaBipModal({ isOpen, onClose, lojaDestinoId, lojaDestinoNome }: Props) {
45	  const [recebidos, setRecebidos] = useState<RecebidoItem[]>([]);
46	
47	  const handleBip = async (payload: ScannedPayload) => {
48	    if (!payload.uid) {
49	      playErrorSound();
50	      toast.error("Etiqueta sem UID — não rastreável");
51	      return;
52	    }
53	
54	    // Dedupe local (evita re-bipar a mesma caixa antes do banco refletir)
55	    if (recebidos.some((r) => r.uid === payload.uid)) {
56	      playErrorSound();
57	      toast.error("Caixa já recebida nesta sessão");
58	      return;
59	    }
60	
61	    // 1. RPC — valida transição + atualiza loja_atual_id
62	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
63	    const { data: rpc, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
64	      p_uid: payload.uid,
65	      p_etapa: "entrada",
66	      p_contexto: {
67	        loja_id: lojaDestinoId,
68	        referencia_tipo: "recebimento",
69	        payload,
70	      },
71	    });
72	    if (rpcErr) {
73	      playErrorSound();
74	      toast.error(`Falha no bip: ${rpcErr.message}`);
75	      return;
76	    }
77	    const result = rpc as {
78	      ok: boolean;
79	      erro?: string;
80	      etiqueta?: {
81	        produto_master_id: number;
82	        produto_nome_snapshot: string | null;
83	        lote_id: string | null;
84	        lote_codigo_snapshot: string | null;
85	        quantidade_interna: number;
86	        embalagem_nome?: string | null;
87	      };
88	      alertas?: string[];
89	      backfilled?: boolean;
90	    };
91	    if (!result?.ok || !result.etiqueta) {
92	      playErrorSound();
93	      toast.error(formatBipError(result?.erro, "entrada"));
94	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
95	      return;
96	    }
97	
98	    const et = result.etiqueta;
99	    const qty = Number(et.quantidade_interna || 1);
100	
101	    // 2. INSERT movimentacao tipo=entrada — trigger cuida do saldo
102	    const { data: estoqueAtual } = await supabase
103	      .from("estoque")
104	      .select("quantidade_atual")
105	      .eq("produto_master_id", et.produto_master_id)
106	      .eq("loja_id", lojaDestinoId)
107	      .maybeSingle();
108	
109	    const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
110	    const nova = anterior + qty;
111	
112	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
113	    const { error: movErr } = await (supabase.from("movimentacoes") as any).insert({
114	      produto_master_id: et.produto_master_id,
115	      tipo_movimentacao: "entrada",
116	      quantidade: qty,
117	      quantidade_anterior: anterior,
118	      quantidade_nova: nova,
119	      motivo: "recebimento",
120	      observacoes: `Recebimento por bip — UID ${payload.uid}`,
121	      data_movimentacao: new Date().toISOString(),
122	      loja_id: lojaDestinoId,
123	      lote_id: et.lote_id,
124	      etiqueta_qr_uid: payload.uid,
125	    });
126	
127	    if (movErr) {
128	      playErrorSound();
129	      toast.error(`Erro ao registrar entrada: ${movErr.message}`);
130	      return;
131	    }
132	
133	    playSuccessSound();
134	    if (navigator.vibrate) navigator.vibrate(100);
135	    toast.success(`Recebido: ${et.produto_nome_snapshot || `#${et.produto_master_id}`} (${qty} un)`);
136	    (result.alertas ?? []).forEach((a) => {
137	      playWarningSound();
138	      toast.warning(a);
139	    });
140	
141	    setRecebidos((prev) => [
142	      {
143	        uid: payload.uid,
144	        produto_master_id: et.produto_master_id,
145	        produto_nome: et.produto_nome_snapshot || `Produto #${et.produto_master_id}`,
146	        lote_codigo: et.lote_codigo_snapshot,
147	        lote_id: et.lote_id,
148	        quantidade: qty,
149	        embalagem: et.embalagem_nome ?? null,
150	        recebido_at: Date.now(),
151	        alertas: result.alertas ?? [],
152	        backfilled: !!result.backfilled,
153	      },
154	      ...prev,
155	    ]);
156	  };
157	
158	  const scanner = useEtiquetaScanner({
159	    enabled: isOpen,
160	    onScan: handleBip,
161	    cameraElementId: "entrada-qr-reader",
162	    onInvalid: () => toast.error("QR ilegível"),
163	    onDuplicate: () => {
164	      playErrorSound();
165	      toast.error("Esta etiqueta já foi bipada");
166	      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
167	    },
168	  });
169	
170	  const stats = useMemo(() => {
171	    const totalCaixas = recebidos.length;
172	    const totalUn = recebidos.reduce((acc, r) => acc + r.quantidade, 0);
173	    const produtosUnicos = new Set(recebidos.map((r) => r.produto_master_id)).size;
174	    return { totalCaixas, totalUn, produtosUnicos };
175	  }, [recebidos]);
176	
177	  // Agregação por produto: caixas + un totais por produto_master_id
178	  const porProduto = useMemo(() => {
179	    const map = new Map<number, { nome: string; embalagem: string | null; caixas: number; un: number }>();
180	    for (const r of recebidos) {
181	      const cur = map.get(r.produto_master_id) ?? { nome: r.produto_nome, embalagem: r.embalagem, caixas: 0, un: 0 };
182	      cur.caixas += 1;
183	      cur.un += r.quantidade;
184	      map.set(r.produto_master_id, cur);
185	    }
186	    return Array.from(map.entries())
187	      .map(([pid, v]) => ({ pid, ...v }))
188	      .sort((a, b) => b.un - a.un);
189	  }, [recebidos]);
190	
191	  return (
192	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
193	      <DialogContent data-mia-modal="recebimento-por-bip" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
194	        {/* Header */}
195	        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
196	          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
197	            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
198	              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
199	            </Button>
200	            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
201	              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
202	            </div>
203	            <div className="min-w-0 flex-1">
204	              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">Recebimento por bip</DialogTitle>
205	              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
206	                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
207	              </p>
208	            </div>
209	          </div>
210	          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
211	            <button
212	              onClick={() => scanner.setScanMode("bluetooth")}
213	              aria-label="Scanner Bluetooth"
214	              className={cn(
215	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
216	                scanner.scanMode === "bluetooth" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
217	              )}
218	            >
219	              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
220	            </button>
221	            <button
222	              onClick={() => scanner.setScanMode("camera")}
223	              aria-label="Scanner por câmera"
224	              className={cn(
225	                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
226	                scanner.scanMode === "camera" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
227	              )}
228	            >
229	              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
230	            </button>
231	          </div>
232	        </div>
233	
234	        {/* Stats */}
235	        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-3 gap-2 sm:gap-3">
236	          <Stat label="Caixas" value={stats.totalCaixas} icon={<Boxes className="w-3 h-3" />} />
237	          <Stat label="Unidades" value={stats.totalUn} />
238	          <Stat label="Produtos" value={stats.produtosUnicos} />
239	        </div>
240	
241	        {/* Scanner input invisível */}
242	        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}
243	
244	        {/* Body */}
245	        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
246	          {scanner.scanMode === "camera" ? (
247	            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
248	              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
249	              <CameraScannerStatus
250	                starting={scanner.cameraStarting}
251	                error={scanner.cameraError}
252	                onRetry={scanner.retryCamera}
253	              />
254	            </div>
255	          ) : (
256	            <div
257	              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
258	              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
259	            >
260	              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
261	                <Bluetooth className="w-9 h-9 text-[#57715B]" />
262	                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
263	              </div>
264	              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Escaneando...</h3>
265	              <p className="text-[11px] text-muted-foreground text-center mt-1">Aponte para cada caixa que chega</p>
266	            </div>
267	          )}
268	
269	          {/* Lista cumulativa */}
270	          <div className="flex-1 flex flex-col overflow-hidden p-2">
271	            <ScrollArea className="flex-1">
272	              <div className="p-2.5 space-y-3">
273	                {/* Agregação por produto */}
274	                {porProduto.length > 0 && (
275	                  <div className="space-y-1.5">
276	                    <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
277	                      Total por produto
278	                    </p>
279	                    {porProduto.map((p) => (
280	                      <div key={p.pid} className="rounded-xl border-2 border-emerald-500/30 bg-emerald-500/5 p-2.5 flex items-center justify-between gap-2">
281	                        <p className="text-sm font-semibold leading-tight truncate flex-1 min-w-0">{p.nome}</p>
282	                        <div className="flex items-center gap-2 text-[11px] text-emerald-700 font-bold flex-shrink-0">
283	                          <span className="inline-flex items-center gap-0.5"><Boxes className="w-3 h-3" />{p.caixas}</span>
284	                          <span className="text-muted-foreground">·</span>
285	                          <span>{p.un} un</span>
286	                        </div>
287	                      </div>
288	                    ))}
289	                  </div>
290	                )}
291	
292	                {/* Cards individuais */}
293	                <div className="space-y-2 pt-2 border-t border-border/30">
294	                  <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
295	                    Caixas recebidas ({recebidos.length})
296	                  </p>
297	                  {recebidos.length === 0 ? (
298	                    <div className="flex flex-col items-center justify-center py-10 text-muted-foreground/40">
299	                      <Package className="w-12 h-12 mb-2" />
300	                      <p className="text-sm font-semibold">Nenhuma caixa recebida ainda</p>
301	                      <p className="text-[11px] mt-1">Bipa a primeira caixa pra começar</p>
302	                    </div>
303	                  ) : (
304	                    recebidos.map((r) => <RecebidoCard key={r.uid} item={r} />)
305	                  )}
306	                </div>
307	              </div>
308	            </ScrollArea>
309	          </div>
310	        </div>
311	
312	        {/* Footer */}
313	        <div
314	          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between gap-2 flex-shrink-0"
315	          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
316	        >
317	          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
318	            {recebidos.length === 0 ? "Aguardando primeira caixa…" : `${stats.totalCaixas} caixa(s) confirmada(s).`}
319	          </p>
320	          <Button data-mia-action="on-close" onClick={onClose} className="h-11 flex-shrink-0">Encerrar</Button>
321	        </div>
