/**
 * Modal de recebimento na loja com bip QR.
 *
 * Operador da loja destino bipa cada caixa que está descarregando.
 * Para cada UID:
 *   1. RPC bipar_etiqueta(uid, 'entrada', { loja_id }) — atomic state machine
 *   2. INSERT movimentacoes (tipo='entrada', etiqueta_qr_uid, lote_id, qty)
 *   3. Trigger atualizar_estoque_e_alertas atualiza estoque automaticamente
 *
 * Lista cumulativa de caixas recebidas, com toast por bip.
 */
import { useMemo, useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { ScrollArea } from "@/shared/ui/scroll-area";
import { Bluetooth, Camera, ScanBarcode, ArrowLeft, Package, MapPin, AlertTriangle, RefreshCw, Boxes } from "lucide-react";
import { toast } from "sonner";
import { Link } from "react-router-dom";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import { useEtiquetaScanner, playSuccessSound, playErrorSound, playWarningSound, formatBipError, type ScannedPayload } from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "./CameraScannerStatus";

interface RecebidoItem {
  uid: string;
  produto_master_id: number;
  produto_nome: string;
  lote_codigo: string | null;
  lote_id: string | null;
  quantidade: number;
  embalagem: string | null;
  recebido_at: number;
  alertas: string[];
  backfilled: boolean;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  lojaDestinoId: number;
  lojaDestinoNome: string;
}

export function EntradaBipModal({ isOpen, onClose, lojaDestinoId, lojaDestinoNome }: Props) {
  const [recebidos, setRecebidos] = useState<RecebidoItem[]>([]);

  const handleBip = async (payload: ScannedPayload) => {
    if (!payload.uid) {
      playErrorSound();
      toast.error("Etiqueta sem UID — não rastreável");
      return;
    }

    // Dedupe local (evita re-bipar a mesma caixa antes do banco refletir)
    if (recebidos.some((r) => r.uid === payload.uid)) {
      playErrorSound();
      toast.error("Caixa já recebida nesta sessão");
      return;
    }

    // 1. RPC — valida transição + atualiza loja_atual_id
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: rpc, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
      p_uid: payload.uid,
      p_etapa: "entrada",
      p_contexto: {
        loja_id: lojaDestinoId,
        referencia_tipo: "recebimento",
        payload,
      },
    });
    if (rpcErr) {
      playErrorSound();
      toast.error(`Falha no bip: ${rpcErr.message}`);
      return;
    }
    const result = rpc as {
      ok: boolean;
      erro?: string;
      etiqueta?: {
        produto_master_id: number;
        produto_nome_snapshot: string | null;
        lote_id: string | null;
        lote_codigo_snapshot: string | null;
        quantidade_interna: number;
        embalagem_nome?: string | null;
      };
      alertas?: string[];
      backfilled?: boolean;
    };
    if (!result?.ok || !result.etiqueta) {
      playErrorSound();
      toast.error(formatBipError(result?.erro, "entrada"));
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    const et = result.etiqueta;
    const qty = Number(et.quantidade_interna || 1);

    // 2. INSERT movimentacao tipo=entrada — trigger cuida do saldo
    const { data: estoqueAtual } = await supabase
      .from("estoque")
      .select("quantidade_atual")
      .eq("produto_master_id", et.produto_master_id)
      .eq("loja_id", lojaDestinoId)
      .maybeSingle();

    const anterior = (estoqueAtual as { quantidade_atual?: number } | null)?.quantidade_atual ?? 0;
    const nova = anterior + qty;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { error: movErr } = await (supabase.from("movimentacoes") as any).insert({
      produto_master_id: et.produto_master_id,
      tipo_movimentacao: "entrada",
      quantidade: qty,
      quantidade_anterior: anterior,
      quantidade_nova: nova,
      motivo: "recebimento",
      observacoes: `Recebimento por bip — UID ${payload.uid}`,
      data_movimentacao: new Date().toISOString(),
      loja_id: lojaDestinoId,
      lote_id: et.lote_id,
      etiqueta_qr_uid: payload.uid,
    });

    if (movErr) {
      playErrorSound();
      toast.error(`Erro ao registrar entrada: ${movErr.message}`);
      return;
    }

    playSuccessSound();
    if (navigator.vibrate) navigator.vibrate(100);
    toast.success(`Recebido: ${et.produto_nome_snapshot || `#${et.produto_master_id}`} (${qty} un)`);
    (result.alertas ?? []).forEach((a) => {
      playWarningSound();
      toast.warning(a);
    });

    setRecebidos((prev) => [
      {
        uid: payload.uid,
        produto_master_id: et.produto_master_id,
        produto_nome: et.produto_nome_snapshot || `Produto #${et.produto_master_id}`,
        lote_codigo: et.lote_codigo_snapshot,
        lote_id: et.lote_id,
        quantidade: qty,
        embalagem: et.embalagem_nome ?? null,
        recebido_at: Date.now(),
        alertas: result.alertas ?? [],
        backfilled: !!result.backfilled,
      },
      ...prev,
    ]);
  };

  const scanner = useEtiquetaScanner({
    enabled: isOpen,
    onScan: handleBip,
    cameraElementId: "entrada-qr-reader",
    onInvalid: () => toast.error("QR ilegível"),
    onDuplicate: () => {
      playErrorSound();
      toast.error("Esta etiqueta já foi bipada");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    },
  });

  const stats = useMemo(() => {
    const totalCaixas = recebidos.length;
    const totalUn = recebidos.reduce((acc, r) => acc + r.quantidade, 0);
    const produtosUnicos = new Set(recebidos.map((r) => r.produto_master_id)).size;
    return { totalCaixas, totalUn, produtosUnicos };
  }, [recebidos]);

  // Agregação por produto: caixas + un totais por produto_master_id
  const porProduto = useMemo(() => {
    const map = new Map<number, { nome: string; embalagem: string | null; caixas: number; un: number }>();
    for (const r of recebidos) {
      const cur = map.get(r.produto_master_id) ?? { nome: r.produto_nome, embalagem: r.embalagem, caixas: 0, un: 0 };
      cur.caixas += 1;
      cur.un += r.quantidade;
      map.set(r.produto_master_id, cur);
    }
    return Array.from(map.entries())
      .map(([pid, v]) => ({ pid, ...v }))
      .sort((a, b) => b.un - a.un);
  }, [recebidos]);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent data-mia-modal="recebimento-por-bip" className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none">
        {/* Header */}
        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
            </Button>
            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">Recebimento por bip</DialogTitle>
              <p className="text-[11px] sm:text-xs text-muted-foreground flex items-center gap-1 truncate">
                <MapPin className="w-3 h-3 flex-shrink-0" /> <span className="truncate">{lojaDestinoNome}</span>
              </p>
            </div>
          </div>
          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
            <button
              onClick={() => scanner.setScanMode("bluetooth")}
              aria-label="Scanner Bluetooth"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "bluetooth" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
            </button>
            <button
              onClick={() => scanner.setScanMode("camera")}
              aria-label="Scanner por câmera"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "camera" ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
            </button>
          </div>
        </div>

        {/* Stats */}
        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-3 gap-2 sm:gap-3">
          <Stat label="Caixas" value={stats.totalCaixas} icon={<Boxes className="w-3 h-3" />} />
          <Stat label="Unidades" value={stats.totalUn} />
          <Stat label="Produtos" value={stats.produtosUnicos} />
        </div>

        {/* Scanner input invisível */}
        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}

        {/* Body */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          {scanner.scanMode === "camera" ? (
            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
              <CameraScannerStatus
                starting={scanner.cameraStarting}
                error={scanner.cameraError}
                onRetry={scanner.retryCamera}
              />
            </div>
          ) : (
            <div
              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
            >
              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
              </div>
              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Escaneando...</h3>
              <p className="text-[11px] text-muted-foreground text-center mt-1">Aponte para cada caixa que chega</p>
            </div>
          )}

          {/* Lista cumulativa */}
          <div className="flex-1 flex flex-col overflow-hidden p-2">
            <ScrollArea className="flex-1">
              <div className="p-2.5 space-y-3">
                {/* Agregação por produto */}
                {porProduto.length > 0 && (
                  <div className="space-y-1.5">
                    <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
                      Total por produto
                    </p>
                    {porProduto.map((p) => (
                      <div key={p.pid} className="rounded-xl border-2 border-emerald-500/30 bg-emerald-500/5 p-2.5 flex items-center justify-between gap-2">
                        <p className="text-sm font-semibold leading-tight truncate flex-1 min-w-0">{p.nome}</p>
                        <div className="flex items-center gap-2 text-[11px] text-emerald-700 font-bold flex-shrink-0">
                          <span className="inline-flex items-center gap-0.5"><Boxes className="w-3 h-3" />{p.caixas}</span>
                          <span className="text-muted-foreground">·</span>
                          <span>{p.un} un</span>
                        </div>
                      </div>
                    ))}
                  </div>
                )}

                {/* Cards individuais */}
                <div className="space-y-2 pt-2 border-t border-border/30">
                  <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
                    Caixas recebidas ({recebidos.length})
                  </p>
                  {recebidos.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-10 text-muted-foreground/40">
                      <Package className="w-12 h-12 mb-2" />
                      <p className="text-sm font-semibold">Nenhuma caixa recebida ainda</p>
                      <p className="text-[11px] mt-1">Bipa a primeira caixa pra começar</p>
                    </div>
                  ) : (
                    recebidos.map((r) => <RecebidoCard key={r.uid} item={r} />)
                  )}
                </div>
              </div>
            </ScrollArea>
          </div>
        </div>

        {/* Footer */}
        <div
          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between gap-2 flex-shrink-0"
          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
        >
          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
            {recebidos.length === 0 ? "Aguardando primeira caixa…" : `${stats.totalCaixas} caixa(s) confirmada(s).`}
          </p>
          <Button data-mia-action="on-close" onClick={onClose} className="h-11 flex-shrink-0">Encerrar</Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}

function Stat({ label, value, icon }: { label: string; value: number; icon?: React.ReactNode }) {
  return (
    <div className="text-center min-w-0">
      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
        {icon}{label}
      </p>
      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
    </div>
  );
}

function RecebidoCard({ item }: { item: RecebidoItem }) {
  return (
    <Link
      to={`/etiquetas/${item.uid}`}
      className="block rounded-2xl bg-white dark:bg-zinc-900 border border-emerald-500/30 p-3 hover:border-emerald-500/60 transition-colors"
