      <div className="flex items-start gap-3">
        <div className="h-9 w-9 rounded-xl bg-emerald-500/10 flex items-center justify-center flex-shrink-0">
          <Package className="h-4 w-4 text-emerald-600" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-semibold leading-tight truncate">{item.produto_nome}</p>
          <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1">
            {item.lote_codigo && <span>Lote {item.lote_codigo}</span>}
            <span className="font-bold text-emerald-700">+1 {item.embalagem || "caixa"} ({item.quantidade} un)</span>
            <span className="font-mono truncate">{item.uid}</span>
          </div>
          {item.backfilled && (
            <span className="inline-flex items-center gap-1 text-[10px] text-amber-600 mt-1">
              <RefreshCw className="w-3 h-3" /> backfill
            </span>
          )}
          {item.alertas.length > 0 && (
            <div className="mt-1 space-y-0.5">
              {item.alertas.map((a, i) => (
                <span key={i} className="inline-flex items-center gap-1 text-[10px] text-amber-700">
                  <AlertTriangle className="w-3 h-3" /> {a}
                </span>
              ))}
            </div>
          )}
        </div>
      </div>
    </Link>
  );
}

