430	export function isDuplicateBipError(erro: string | null | undefined): boolean {
431	  if (!erro) return false;
432	  const e = erro.toLowerCase();
433	  return e.includes("bip duplicado") || e.includes("já está com status") || e.includes("ja esta com status");
434	}
