533	/**
534	 * Mapeia erros nativos da câmera (DOMException, getUserMedia, html5-qrcode)
535	 * pra mensagens em pt-BR acionáveis pelo operador.
536	 */
537	function describeCameraError(err: unknown): string {
538	  if (typeof err === "string") return err;
539	  const e = err as { name?: string; message?: string };
540	  const name = e?.name || "";
541	  const msg = e?.message || "";
542	  if (name === "NotAllowedError" || /permission/i.test(msg)) {
543	    return "Permissão da câmera negada. Libere o acesso nas configurações do navegador.";
544	  }
545	  if (name === "NotFoundError" || /no.*camera|device not found/i.test(msg)) {
546	    return "Nenhuma câmera detectada neste aparelho.";
547	  }
548	  if (name === "NotReadableError" || /in use|track started/i.test(msg)) {
549	    return "Câmera ocupada por outro app. Feche-o e tente de novo.";
550	  }
551	  if (name === "OverconstrainedError" || /constraints/i.test(msg)) {
552	    return "Câmera traseira indisponível — tentando câmera frontal.";
553	  }
554	  if (name === "SecurityError" || /https|secure context/i.test(msg)) {
555	    return "Câmera só funciona em conexão segura (HTTPS).";
556	  }
557	  if (name === "AbortError") {
558	    return "Inicialização da câmera foi interrompida. Tente abrir de novo.";
559	  }
560	  return msg || "Falha desconhecida ao iniciar a câmera.";
561	}
