339	                          {(ev.tipo_evento === 'retirada_avulsa' || ev.tipo_evento === 'consumida_total') && ev.metadata?.quantidade_retirada !== undefined && (
340	                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-orange-100 text-orange-700 border border-orange-300 text-xs font-bold">
341	                              −{String(ev.metadata.quantidade_retirada)}
342	                              {ev.metadata.quantidade_disponivel_apos !== undefined && (
343	                                <span className="opacity-70 font-normal">· restam {String(ev.metadata.quantidade_disponivel_apos)}</span>
344	                              )}
345	                            </span>
346	                          )}
347	                          {ev.status_anterior && ev.status_novo && ev.status_anterior !== ev.status_novo && (
348	                            <span className="flex items-center gap-1 text-xs text-muted-foreground">
349	                              <StatusBadge status={ev.status_anterior} />
350	                              <ArrowRight className="w-3 h-3" />
351	                              <StatusBadge status={ev.status_novo} />
352	                            </span>
353	                          )}
354	                          {ev.status_anterior == null && ev.status_novo && (
355	                            <StatusBadge status={ev.status_novo} />
356	                          )}
357	                        </div>
358	                        <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
359	                          <span className="inline-flex items-center gap-1">
360	                            <Calendar className="w-3 h-3" />
361	                            {fmtDate(ev.created_at, true)}
362	                          </span>
363	                          {ev.usuario_nome && (
364	                            <span className="inline-flex items-center gap-1">
365	                              <User className="w-3 h-3" /> {ev.usuario_nome}
366	                            </span>
367	                          )}
368	                          {ev.loja_nome && (
369	                            <span className="inline-flex items-center gap-1">
370	                              <MapPin className="w-3 h-3" /> {ev.loja_nome}
371	                            </span>
372	                          )}
373	                          {ev.referencia_tipo && ev.referencia_id && (
374	                            <span className="inline-flex items-center gap-1 font-mono">
375	                              {ev.referencia_tipo}: {ev.referencia_id}
376	                            </span>
377	                          )}
378	                        </div>
379	                      </li>
380	                    );
381	                  })}
382	                </ol>
383	              )}
384	            </CardContent>
385	          </Card>
386	        </>
387	      )}
388	    </div>
389	  );
390	}
391	
392	function Field({
393	  icon: Icon,
394	  label,
395	  children,
396	}: {
397	  icon: React.ElementType;
398	  label: string;
399	  children: React.ReactNode;
400	}) {
401	  return (
402	    <div className="space-y-1">
403	      <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold flex items-center gap-1">
404	        <Icon className="w-3 h-3" /> {label}
405	      </p>
406	      <p className="text-sm font-semibold">{children}</p>
407	    </div>
408	  );
409	}
