import { useEffect, useMemo, useState } from "react";
import { useNavigate, useParams, Link } from "react-router-dom";
import {
  ArrowLeft, Package, MapPin, Calendar, User, AlertTriangle,
  CircleDot, CheckCircle2, Truck, ScanLine, PackageX, RefreshCw, Search, ArrowRight
} from "lucide-react";
import { format } from "date-fns";
import { ptBR } from "date-fns/locale";

import { Card, CardContent, CardHeader, CardTitle } from "@/shared/ui/card";
import { Badge } from "@/shared/ui/badge";
import { Button } from "@/shared/ui/button";
import { Input } from "@/shared/ui/input";
import { Skeleton } from "@/shared/ui/skeleton";
import { supabase } from "@/integrations/supabase/client";
import { cn } from "@/shared/lib/utils";

interface TimelineEvent {
  id: number;
  tipo_evento: string;
  etapa: string;
  status_anterior: string | null;
  status_novo: string | null;
  loja_id: number | null;
  loja_nome: string | null;
  usuario_nome: string | null;
  referencia_tipo: string | null;
  referencia_id: string | null;
  metadata: Record<string, unknown>;
  created_at: string;
}

interface EtiquetaTimeline {
  uid: string;
  produto_master_id: number;
  produto_nome_snapshot: string | null;
  lote_id: string | null;
  lote_codigo_snapshot: string | null;
  lote_validade_snapshot: string | null;
  embalagem_nome: string | null;
  tipo_embalagem: string | null;
  quantidade_interna: number;
  quantidade_disponivel: number | null;
  consumida_inteira: boolean;
  foi_separada: boolean;
  separada_at: string | null;
  foi_conferida: boolean;
  conferida_at: string | null;
  status: string;
  loja_origem_id: number | null;
  loja_origem_nome: string | null;
  loja_atual_id: number | null;
  loja_atual_nome: string | null;
  gerada_at: string | null;
  gerada_por: string | null;
  replaces_uid: string | null;
  replaced_by_uid: string | null;
  backfilled: boolean;
  created_at: string;
  updated_at: string;
  eventos: TimelineEvent[];
}

const STATUS_META: Record<string, { label: string; className: string }> = {
  gerada:        { label: "Gerada",         className: "bg-slate-100 text-slate-700 border-slate-300" },
  em_separacao:  { label: "Em separação",   className: "bg-amber-100 text-amber-800 border-amber-300" },
  separada:      { label: "Separada",       className: "bg-blue-100 text-blue-800 border-blue-300" },
  conferida:     { label: "Conferida",      className: "bg-cyan-100 text-cyan-800 border-cyan-300" },
  em_transito:   { label: "Em trânsito",    className: "bg-indigo-100 text-indigo-800 border-indigo-300" },
  recebida:      { label: "Recebida",       className: "bg-emerald-100 text-emerald-800 border-emerald-300" },
  aberta:        { label: "Aberta",         className: "bg-orange-100 text-orange-800 border-orange-300" },
  consumida:     { label: "Consumida",      className: "bg-stone-200 text-stone-700 border-stone-300" },
  descartada:    { label: "Descartada",     className: "bg-red-100 text-red-800 border-red-300" },
};

const ETAPA_ICON: Record<string, React.ElementType> = {
  geracao:     Package,
  separacao:   CircleDot,
  conferencia: CheckCircle2,
  saida:       Truck,
  entrada:     ScanLine,
  consumo:     PackageX,
  descarte:    PackageX,
  reposicao:   RefreshCw,
  backfill:    AlertTriangle,
};

const ETAPA_LABEL: Record<string, string> = {
  geracao:     "Geração",
  separacao:   "Separação",
  conferencia: "Conferência",
  saida:       "Saída",
  entrada:     "Recebimento",
  consumo:     "Consumo",
  descarte:    "Descarte",
  reposicao:   "Reposição",
  backfill:    "Backfill",
};

function StatusBadge({ status }: { status: string }) {
  const meta = STATUS_META[status] ?? { label: status, className: "bg-gray-100 text-gray-700 border-gray-300" };
  return (
    <Badge variant="outline" className={cn("font-bold uppercase tracking-wide", meta.className)}>
      {meta.label}
    </Badge>
  );
}

function fmtDate(iso: string | null, withTime = false): string {
  if (!iso) return "—";
  try {
    const d = new Date(iso);
    return format(d, withTime ? "dd/MM/yyyy HH:mm" : "dd/MM/yyyy", { locale: ptBR });
  } catch {
    return iso;
  }
}

export default function EtiquetaTimelinePage() {
  const { uid } = useParams<{ uid: string }>();
  const navigate = useNavigate();
  const [data, setData] = useState<EtiquetaTimeline | null>(null);
  const [loading, setLoading] = useState(true);
  const [erro, setErro] = useState<string | null>(null);
  const [searchUid, setSearchUid] = useState("");

  useEffect(() => {
    if (!uid) {
      setLoading(false);
      return;
    }
    setLoading(true);
    setErro(null);
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (supabase.from("view_etiqueta_timeline" as any) as any)
      .select("*")
      .eq("uid", uid)
      .maybeSingle()
      .then(({ data, error }: { data: unknown; error: { message: string } | null }) => {
        if (error) {
          setErro(error.message);
          setData(null);
        } else if (!data) {
          setErro("Etiqueta não encontrada");
          setData(null);
        } else {
          setData(data as unknown as EtiquetaTimeline);
        }
        setLoading(false);
      });
  }, [uid]);

  const eventos = useMemo(() => {
    if (!data?.eventos) return [];
    // Eventos já vêm ordenados ASC pela view
    return [...data.eventos];
  }, [data]);

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = searchUid.trim();
    if (trimmed) navigate(`/etiquetas/${encodeURIComponent(trimmed)}`);
  };

  const validadeVencida =
    data?.lote_validade_snapshot &&
    new Date(data.lote_validade_snapshot) < new Date(new Date().toDateString());

  return (
    <div className="flex flex-col gap-4 sm:gap-6 p-3 sm:p-4 md:p-8 max-w-5xl mx-auto">
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2 sm:gap-4">
        <Button variant="ghost" size="sm" onClick={() => navigate(-1)} className="gap-2 self-start min-h-[44px]">
          <ArrowLeft className="w-4 h-4" /> Voltar
        </Button>
        <form onSubmit={handleSearch} className="flex items-center gap-2 w-full sm:flex-1 sm:max-w-md">
          <div className="relative flex-1">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" />
            <Input data-mia-field="search_uid"
              value={searchUid}
              onChange={(e) => setSearchUid(e.target.value)}
              placeholder="Buscar outro UID…"
              className="pl-9 h-11"
            />
          </div>
          <Button type="submit" size="sm" className="h-11 flex-shrink-0">Rastrear</Button>
        </form>
      </div>

      {loading && (
        <div className="space-y-4">
          <Skeleton className="h-32 w-full" />
          <Skeleton className="h-64 w-full" />
        </div>
      )}

      {!loading && erro && (
        <Card className="border-red-200 bg-red-50/50">
          <CardContent className="p-6 flex items-center gap-3 text-red-700">
            <AlertTriangle className="w-5 h-5" />
            <div>
              <p className="font-bold">{erro}</p>
              <p className="text-sm text-red-600/80">UID: {uid}</p>
            </div>
          </CardContent>
        </Card>
      )}

      {!loading && data && (
        <>
          {/* Header card */}
          <Card className="border-[#57715B]/20 shadow-lg">
            <CardHeader className="pb-3">
              <div className="flex items-start justify-between gap-3 flex-wrap">
                <div className="min-w-0 flex-1">
                  <p className="text-xs uppercase tracking-wider text-muted-foreground font-semibold">
                    Etiqueta UID
                  </p>
                  <CardTitle className="text-lg sm:text-2xl font-mono break-all">{data.uid}</CardTitle>
                  {data.backfilled && (
                    <Badge variant="outline" className="mt-2 bg-amber-50 text-amber-800 border-amber-300">
                      Registrada retroativamente (backfill)
                    </Badge>
                  )}
                </div>
                <div className="flex-shrink-0">
                  <StatusBadge status={data.status} />
                </div>
              </div>
            </CardHeader>
            {/* Saldo do container — destaque grande quando aberto ou consumido */}
            {(data.quantidade_disponivel !== null && data.quantidade_disponivel !== undefined) && (
              <div className={cn(
                "mx-6 mt-3 px-4 py-3 rounded-2xl border-2 flex items-center justify-between",
                data.consumida_inteira
                  ? "bg-stone-100 border-stone-300 text-stone-700"
                  : data.quantidade_disponivel < data.quantidade_interna
                    ? "bg-orange-50 border-orange-300"
                    : "bg-emerald-50 border-emerald-300"
              )}>
                <div>
                  <p className="text-[10px] uppercase font-bold tracking-wider opacity-75">Saldo no container</p>
                  <div className="flex items-baseline gap-2 mt-0.5">
                    <span className="text-3xl font-black tabular-nums">{data.quantidade_disponivel}</span>
                    <span className="text-sm font-bold opacity-70">{data.embalagem_nome || "un"}</span>
                    <span className="text-xs opacity-60">de {data.quantidade_interna}</span>
                  </div>
                </div>
                <Badge variant="outline" className={cn(
                  "text-[10px] font-bold uppercase",
                  data.consumida_inteira ? "bg-stone-200 text-stone-700 border-stone-400"
                    : data.quantidade_disponivel < data.quantidade_interna ? "bg-orange-100 text-orange-700 border-orange-400"
                    : "bg-emerald-100 text-emerald-700 border-emerald-400"
                )}>
                  {data.consumida_inteira ? "Container vazio"
                    : data.quantidade_disponivel < data.quantidade_interna ? "Aberto"
                    : "Cheio"}
                </Badge>
              </div>
            )}
            <CardContent className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-3 gap-3 sm:gap-4 pt-4">
              <Field icon={Package} label="Produto">
                {data.produto_nome_snapshot || `#${data.produto_master_id}`}
              </Field>
              <Field icon={Package} label="Embalagem">
                <span className="font-bold uppercase">{data.tipo_embalagem || "caixa"}</span>
                {" · "}
                {data.quantidade_interna} {data.embalagem_nome || "un"}
              </Field>
              {/* Marcos de separação/conferência */}
              {data.foi_separada && (
                <Field icon={CircleDot} label="Separada em">
                  {fmtDate(data.separada_at, true)}
                </Field>
              )}
              {data.foi_conferida && (
                <Field icon={CheckCircle2} label="Conferida em">
                  {fmtDate(data.conferida_at, true)}
                </Field>
              )}
              <Field icon={Calendar} label="Lote">
                {data.lote_codigo_snapshot || "—"}
              </Field>
              <Field icon={Calendar} label="Validade">
                <span className={cn(validadeVencida && "text-red-600 font-bold")}>
                  {fmtDate(data.lote_validade_snapshot)}
                  {validadeVencida && " (VENCIDO)"}
                </span>
              </Field>
              <Field icon={MapPin} label="Origem">
                {data.loja_origem_nome || "—"}
              </Field>
              <Field icon={MapPin} label="Loja atual">
                {data.loja_atual_nome || "—"}
              </Field>
              <Field icon={Calendar} label="Gerada em">
                {fmtDate(data.gerada_at, true)}
              </Field>
              {data.replaces_uid && (
                <Field icon={RefreshCw} label="Substitui">
                  <Link to={`/etiquetas/${data.replaces_uid}`} className="text-blue-700 hover:underline font-mono">
                    {data.replaces_uid}
                  </Link>
                </Field>
              )}
              {data.replaced_by_uid && (
                <Field icon={RefreshCw} label="Substituída por">
                  <Link to={`/etiquetas/${data.replaced_by_uid}`} className="text-blue-700 hover:underline font-mono">
                    {data.replaced_by_uid}
                  </Link>
                </Field>
              )}
            </CardContent>
          </Card>

          {/* Timeline */}
          <Card className="border-[#57715B]/20 shadow-lg">
            <CardHeader>
              <CardTitle className="text-lg">Linha do tempo ({eventos.length})</CardTitle>
            </CardHeader>
            <CardContent>
              {eventos.length === 0 ? (
                <p className="text-sm text-muted-foreground py-8 text-center">Sem eventos registrados.</p>
              ) : (
                <ol className="relative border-l-2 border-[#57715B]/20 ml-3 space-y-6">
                  {eventos.map((ev) => {
                    const Icon = ETAPA_ICON[ev.etapa] || CircleDot;
                    return (
                      <li key={ev.id} className="ml-6 relative">
                        <span className="absolute -left-[34px] flex h-7 w-7 items-center justify-center rounded-full bg-[#57715B] text-white shadow-md ring-4 ring-white">
                          <Icon className="w-3.5 h-3.5" />
                        </span>
                        <div className="flex flex-wrap items-center gap-2 mb-1">
                          <span className="font-bold text-sm uppercase tracking-wide text-[#57715B]">
                            {ev.tipo_evento === 'retirada_avulsa' ? 'Retirada avulsa'
                              : ev.tipo_evento === 'consumida_total' ? 'Consumido totalmente'
                              : ETAPA_LABEL[ev.etapa] || ev.etapa}
                          </span>
                          {/* Quantidade retirada em destaque pra eventos de saída avulsa */}
                          {(ev.tipo_evento === 'retirada_avulsa' || ev.tipo_evento === 'consumida_total') && ev.metadata?.quantidade_retirada !== undefined && (
                            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-orange-100 text-orange-700 border border-orange-300 text-xs font-bold">
                              −{String(ev.metadata.quantidade_retirada)}
                              {ev.metadata.quantidade_disponivel_apos !== undefined && (
                                <span className="opacity-70 font-normal">· restam {String(ev.metadata.quantidade_disponivel_apos)}</span>
                              )}
                            </span>
                          )}
                          {ev.status_anterior && ev.status_novo && ev.status_anterior !== ev.status_novo && (
                            <span className="flex items-center gap-1 text-xs text-muted-foreground">
                              <StatusBadge status={ev.status_anterior} />
                              <ArrowRight className="w-3 h-3" />
                              <StatusBadge status={ev.status_novo} />
                            </span>
                          )}
                          {ev.status_anterior == null && ev.status_novo && (
                            <StatusBadge status={ev.status_novo} />
                          )}
                        </div>
                        <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs text-muted-foreground">
                          <span className="inline-flex items-center gap-1">
                            <Calendar className="w-3 h-3" />
                            {fmtDate(ev.created_at, true)}
                          </span>
                          {ev.usuario_nome && (
                            <span className="inline-flex items-center gap-1">
                              <User className="w-3 h-3" /> {ev.usuario_nome}
                            </span>
                          )}
                          {ev.loja_nome && (
                            <span className="inline-flex items-center gap-1">
                              <MapPin className="w-3 h-3" /> {ev.loja_nome}
                            </span>
                          )}
                          {ev.referencia_tipo && ev.referencia_id && (
                            <span className="inline-flex items-center gap-1 font-mono">
                              {ev.referencia_tipo}: {ev.referencia_id}
                            </span>
                          )}
                        </div>
                      </li>
                    );
                  })}
                </ol>
              )}
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}

function Field({
  icon: Icon,
  label,
  children,
}: {
  icon: React.ElementType;
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1">
      <p className="text-[10px] uppercase tracking-wider text-muted-foreground font-bold flex items-center gap-1">
        <Icon className="w-3 h-3" /> {label}
      </p>
      <p className="text-sm font-semibold">{children}</p>
    </div>
  );
}

